<template>
  <div class="commerce-page">
    <header class="commerce-heading"><div><p class="eyebrow">{{ product ? 'THOUGHTFULLY SELECTED' : 'TELL YOUR STORY' }}</p><h1>{{ product ? '我的商品' : '广告投放' }} <span class="heading-count">{{ total }}</span></h1><p class="intro">{{ product ? '把好物准备妥当，等待与校园日常相遇。' : '用一张图片、一段故事，让更多师生发现你的商品。' }}</p></div><el-button type="primary" size="large" @click="openEditor()"><i class="ph ph-plus" /> {{ product ? '发布新商品' : '申请投放广告' }}</el-button></header>
    <div class="toolbar"><div class="filter-pills"><button v-for="f in filters" :key="f.value" :class="{active:status===f.value}" @click="status=f.value;page=1;load()">{{ f.label }}</button></div><el-button text :loading="loading" @click="load"><i class="ph ph-arrows-clockwise" /> 刷新</el-button></div>
    <div v-loading="loading" style="min-height:200px"><div v-if="rows.length" class="commerce-grid"><article v-for="item in rows" :key="item.id" class="catalog-card"><div class="catalog-cover"><img :src="item.imageUrl" :alt="item.title" /><CommerceStatus :status="item.reviewStatus" /></div><div class="catalog-body"><h3>{{ item.title }}</h3><p>{{ item.content }}</p><div class="catalog-meta"><strong v-if="product||item.targetType!=='MERCHANT'" class="catalog-price">¥ {{ Number(item.price).toFixed(2) }}</strong><strong v-else class="catalog-price" style="font-size:15px">店铺推广</strong><span>{{ product ? user.profile?.city+'发货' : item.targetType==='MERCHANT'?'关联 · 商家主页':'关联 · '+item.productTitle }}</span></div><div v-if="item.reviewReason" class="review-reason">{{ item.reviewReason }}</div><div v-if="!product && item.targetType!=='MERCHANT' && (item.productStatus!=='APPROVED' || item.productWithdrawn)" class="review-reason">关联商品未上架，广告暂不展示。</div><p v-if="!product && item.reviewStatus==='APPROVED'" class="editor-help">{{ item.carouselEnabled?'已加入首页轮播':'审核已通过，等待管理员安排轮播' }}</p><div class="catalog-actions"><el-button text @click="openEditor(item)"><i class="ph ph-pencil-simple" /> 编辑{{ product ? '商品' : '广告' }}</el-button><el-button v-if="item.reviewStatus!=='WITHDRAWN'" text type="danger" @click="withdraw(item)">撤回{{ item.reviewStatus==='APPROVED' ? ' / 下架' : '' }}</el-button></div></div></article></div><div v-else class="surface"><el-empty :description="product ? '这里还没有商品，发布你的第一份好物吧' : '这里还没有广告，先为已上架商品设计一份广告吧'"><el-button type="primary" @click="openEditor()">{{ product ? '发布商品' : '设计广告' }}</el-button></el-empty></div></div>
    <el-pagination v-if="total>12" v-model:current-page="page" class="commerce-pager" :page-size="12" :total="total" layout="total, prev, pager, next" @current-change="load" />
    <el-dialog v-model="visible" :title="(form.id?'编辑':'新建')+(product?'商品':'广告申请')" width="1030px" top="5vh" class="commerce-dialog" destroy-on-close :close-on-click-modal="false" :before-close="closeEditor">
      <el-form ref="formRef" :model="form" :rules="rules" label-position="top" size="large"><div class="editor-grid"><div><section class="form-section"><h3 class="section-title"><span>01</span> {{ product ? '商品基本信息' : '广告内容与关联商品' }}</h3><el-form-item :label="product?'商品名称':'广告标题'" prop="title"><el-input v-model="form.title" :placeholder="product?'用简洁的名称介绍你的商品':'让人想要多看一眼的标题'" maxlength="100" show-word-limit /></el-form-item><el-form-item v-if="!product" label="广告关联方式"><el-radio-group v-model="form.targetType"><el-radio-button value="PRODUCT">关联商品</el-radio-button><el-radio-button value="MERCHANT">关联商家主页</el-radio-button></el-radio-group><p v-if="form.targetType==='MERCHANT'" class="editor-help">点击广告将进入你的商家主页；至少有一件审核上架的商品时才可申请。</p></el-form-item><el-form-item v-if="!product && form.targetType==='PRODUCT'" label="关联自有商品" prop="productId"><el-select v-model="form.productId" style="width:100%" filterable remote :remote-method="searchProducts" :loading="optionsLoading" placeholder="搜索并选择自己的已上架商品"><el-option v-for="p in options" :key="p.id" :label="p.title" :value="p.id"><span>{{ p.title }}</span><span style="float:right;color:#9ba78b;margin-left:20px">¥{{ p.price }}</span></el-option></el-select></el-form-item><el-form-item v-if="product" label="商品售价（元）" prop="price"><el-input-number v-model="form.price" :min="0.01" :max="99999999.99" :precision="2" :step="1" controls-position="right" style="width:100%" /></el-form-item><el-form-item :label="product?'商品简介':'广告文案'" prop="content"><el-input v-model="form.content" type="textarea" :rows="4" maxlength="1000" show-word-limit :placeholder="product?'介绍商品的特点、材质或使用场景':'讲述商品的亮点，让校园生活多一份灵感'" /></el-form-item><el-form-item :label="product?'商品封面':'广告主图'" prop="imageUrl"><CommerceImageField v-model="form.imageUrl" @busy="uploading=$event" /></el-form-item></section><section v-if="product" class="form-section"><h3 class="section-title"><span>02</span> 图文详情</h3><p class="editor-help">添加文字、插入图片，按顺序讲好商品的故事。</p><BlockEditor v-model="form.blocks" @busy="detailUploading=$event" /></section></div><aside class="editor-preview"><small>LIVE PREVIEW · 展示预览</small><img v-if="form.imageUrl" class="preview-cover" :src="form.imageUrl" alt="展示预览" /><div v-else class="preview-placeholder"><i class="ph ph-image" /></div><h3>{{ form.title || (product?'你的下一份好物':'值得被发现的故事') }}</h3><p>{{ form.content || '你填写的介绍文案会展示在这里。' }}</p><strong v-if="product" class="preview-price">¥ {{ Number(form.price || 0).toFixed(2) }}</strong><p><i class="ph ph-storefront" /> {{ user.profile?.name }} · {{ user.profile?.city }}发货</p><ContentBlocks v-if="product" :value="form.blocks" /><div class="preview-note"><i class="ph ph-seal-check" /> 提交后由管理员审核，通过后{{ product?'进入周边商城':'可由管理员安排加入首页轮播' }}。修改已通过内容会重新审核。</div></aside></div></el-form>
      <template #footer><div class="dialog-footer"><span>发布前请核对文字、图片与{{ product?'商品价格':'关联商品' }}。</span><div><el-button :disabled="saving||uploading||detailUploading" @click="closeEditor()">取消</el-button><el-button type="primary" :loading="saving" :disabled="uploading||detailUploading" @click="submit">提交审核 <i class="ph ph-arrow-right" /></el-button></div></div></template>
    </el-dialog>
  </div>
</template>
<script setup>
import { computed, onMounted, reactive, ref } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { useUserStore } from '@/stores/user'
import { ElMessage, ElMessageBox } from 'element-plus'
import { merchantList, saveMerchantItem, withdrawMerchantItem, productOptions } from '@/api/merchant'
import CommerceStatus from '@/components/CommerceStatus.vue'
import CommerceImageField from '@/components/CommerceImageField.vue'
import BlockEditor from '@/components/BlockEditor.vue'
import ContentBlocks from '@/components/ContentBlocks.vue'
const props=defineProps({kind:String}),product=computed(()=>props.kind==='products'),user=useUserStore(),route=useRoute(),router=useRouter()
const rows=ref([]),total=ref(0),page=ref(1),status=ref(''),loading=ref(false),visible=ref(false),saving=ref(false),uploading=ref(false),detailUploading=ref(false),formRef=ref(),options=ref([]),optionsLoading=ref(false)
const filters=[{value:'',label:'全部'},{value:'PENDING',label:'等待审核'},{value:'APPROVED',label:'已通过'},{value:'REJECTED',label:'未通过'},{value:'WITHDRAWN',label:'已撤回'}]
const form=reactive({id:null,revision:null,title:'',content:'',imageUrl:'',price:1,productId:null,targetType:'PRODUCT',blocks:'[]'})
const rules={title:[{required:true,message:'请填写标题',trigger:'blur'}],content:[{required:true,message:'请填写介绍文案',trigger:'blur'}],imageUrl:[{required:true,message:'请上传封面图片',trigger:'change'}],productId:[{required:true,message:'请选择自己的已上架商品',trigger:'change'}],price:[{required:true,message:'请设置价格',trigger:'change'}]}
let loadVersion=0,searchVersion=0
async function load(){const stamp=++loadVersion;loading.value=true;try{const r=await merchantList(props.kind,{page:page.value,size:12,status:status.value});if(stamp!==loadVersion)return;rows.value=r.data.list;total.value=r.data.total;if(!rows.value.length&&page.value>1){page.value--;await load()}}catch{}finally{if(stamp===loadVersion)loading.value=false}}
async function searchProducts(keyword=''){const stamp=++searchVersion;optionsLoading.value=true;try{const r=await productOptions(keyword);if(stamp===searchVersion)options.value=r.data}catch{}finally{if(stamp===searchVersion)optionsLoading.value=false}}
async function openEditor(item){Object.assign(form,{id:null,revision:null,title:'',content:'',imageUrl:'',price:1,productId:null,targetType:'PRODUCT',blocks:'[]'},item||{});if(!product.value){await searchProducts();if(item&&item.targetType!=='MERCHANT'&&!options.value.some(p=>p.id===item.productId))options.value.unshift({id:item.productId,title:item.productTitle,price:item.price})}visible.value=true}
function closeEditor(done){if(saving.value||uploading.value||detailUploading.value)return;if(typeof done==='function')done();else visible.value=false}
async function submit(){if(saving.value||uploading.value||detailUploading.value)return;const valid=await formRef.value.validate().catch(()=>false);if(!valid)return;if(product.value){let b;try{b=JSON.parse(form.blocks)}catch{b=[]}if(!b.some(x=>x.value?.trim())){ElMessage.warning('请添加商品图文详情');return}}saving.value=true;try{await saveMerchantItem(props.kind,{...form});ElMessage.success('已提交，等待管理员审核');visible.value=false;page.value=1;status.value='';await load()}catch{}finally{saving.value=false}}
async function withdraw(item){const ok=await ElMessageBox.confirm(product.value?'撤回后商品将从商城下架，关联广告也将暂停展示。历史订单仍可处理。':'撤回后广告将停止在首页展示。','确认撤回',{type:'warning',confirmButtonText:'确认撤回',cancelButtonText:'继续保留'}).then(()=>true).catch(()=>false);if(!ok)return;try{await withdrawMerchantItem(props.kind,item.id);ElMessage.success('已撤回');await load()}catch{}}
onMounted(async()=>{await load();if(route.query.create){openEditor();router.replace({path:route.path,query:{}})}})
</script>
<style scoped>
.heading-count{font-size:14px;font-weight:400;letter-spacing:0;color:#9ba48c;margin-left:10px}.commerce-heading .el-button i{margin-right:8px}.catalog-actions i{margin-right:6px}.catalog-meta>span{max-width:60%;text-align:right;line-height:1.8}.editor-help{font-size:12px;color:#93a084;line-height:1.8;margin-bottom:20px}.preview-placeholder{height:170px;border:1px dashed #cad2bb;border-radius:12px;display:grid;place-items:center;color:#b0b99d;font-size:35px}.preview-note{font-size:11px;line-height:1.9;color:#8f9b7b;border-top:1px solid #dce1cf;padding-top:15px;margin-top:20px}
</style>
